import stylesText from './food-card.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { formatMacro } from '../../../../utils/format-macro.js';
import { unitLabel } from '../../../../utils/line-view.js';
import { createFoodCardSelectEvent, type FoodCardEntry } from '../../health-events.js';
import '../../food-thumbnail/food-thumbnail.component.js';
import '../provenance-badge/provenance-badge.component.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
    <button type="button" class="card" part="card">
        <food-thumb></food-thumb>
        <span class="text">
            <span class="name"><provenance-badge hidden></provenance-badge><span class="title"></span></span>
            <span class="sub"></span>
        </span>
        <span class="kcal"><b class="kcal-value"></b><span class="kcal-basis"></span></span>
    </button>
`;

/** What a card says about its kcal: per base for a food, the whole meal for a meal. */
function describe(entry: FoodCardEntry): { title: string; sub: string; kcal: string; basis: string; badge: string | null; path: string | null; remote: string | null } {
    if (entry.kind === 'food') {
        const f = entry.item;
        const per = f.base_unit === 'piece' && f.base_amount === 1 ? '/pc' : `/${formatMacro(f.base_amount)}${unitLabel(f.base_unit)}`;
        return {
            title: f.display_name, sub: f.brand ?? 'your library', kcal: formatMacro(f.calories_per_base), basis: per,
            badge: null, path: f.image_path, remote: null,
        };
    }
    if (entry.kind === 'meal') {
        const count = entry.ingredient_count;
        return {
            title: entry.meal.name, sub: count === undefined ? 'meal' : `${count} ingredient${count === 1 ? '' : 's'}`,
            kcal: entry.calories === undefined ? '' : formatMacro(entry.calories), basis: '',
            badge: 'meal', path: entry.meal.image_path, remote: null,
        };
    }
    const p = entry.product;
    return {
        title: p.product_name, sub: p.brands ?? '', kcal: formatMacro(p.calories_per_100g), basis: '/100g',
        badge: 'off', path: null, remote: p.image_url ?? null,
    };
}

/**
 * Story 420 — one food, meal or Open Food Facts product as a row (`variant="row"`, the
 * default) or a tile (`variant="tile"`, the frequent grid). Set `.entry`; a tap emits
 * `health:food-card-select` with it.
 */
export class FoodCard extends HTMLElement {
    static get observedAttributes() { return ['variant']; }

    private entryValue: FoodCardEntry | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        shadow.querySelector('.card')!.addEventListener('click', () => {
            if (this.entryValue) this.dispatchEvent(createFoodCardSelectEvent({ entry: this.entryValue }));
        });
    }

    get entry(): FoodCardEntry | null { return this.entryValue; }
    set entry(value: FoodCardEntry) {
        this.entryValue = value;
        this.render();
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private render(): void {
        const shadow = this.shadowRoot!;
        const card = shadow.querySelector('.card') as HTMLElement;
        card.classList.toggle('tile', this.getAttribute('variant') === 'tile');
        if (!this.entryValue) return;
        const d = describe(this.entryValue);
        (shadow.querySelector('.title') as HTMLElement).textContent = d.title;
        (shadow.querySelector('.sub') as HTMLElement).textContent = d.sub;
        (shadow.querySelector('.kcal-value') as HTMLElement).textContent = d.kcal;
        (shadow.querySelector('.kcal-basis') as HTMLElement).textContent = d.basis;
        const badge = shadow.querySelector('provenance-badge') as HTMLElement;
        badge.hidden = d.badge === null;
        if (d.badge !== null) badge.setAttribute('kind', d.badge);
        const thumb = shadow.querySelector('food-thumb') as HTMLElement;
        if (d.path) thumb.setAttribute('path', d.path); else thumb.removeAttribute('path');
        if (d.remote) thumb.setAttribute('remote', d.remote); else thumb.removeAttribute('remote');
        card.setAttribute('aria-label', [d.title, d.sub, d.kcal && `${d.kcal} kcal${d.basis}`].filter(Boolean).join(', '));
    }
}

if (!customElements.get('food-card')) {
    customElements.define('food-card', FoodCard);
}
